35	func newCRTBHandler(uc *config.UserContext) (*crtbHandler, error) {
36		impersonator, err := impersonation.ForCluster(uc)
37		if err != nil {
38			return nil, err
39		}
40		return &crtbHandler{
41			impersonationHandler: &impersonationHandler{
42				clusterName:  uc.ClusterName,
43				impersonator: impersonator,
44				crClient:     uc.RBACw.ClusterRole(),
45				crtbCache:    uc.Management.Wrangler.Mgmt.ClusterRoleTemplateBinding().Cache(),
46				prtbCache:    uc.Management.Wrangler.Mgmt.ProjectRoleTemplateBinding().Cache(),
47			},
48			crbClient:   uc.RBACw.ClusterRoleBinding(),
49			crtbCache:   uc.Management.Wrangler.Mgmt.ClusterRoleTemplateBinding().Cache(),
50			crtbClient:  uc.Management.Wrangler.Mgmt.ClusterRoleTemplateBinding(),
51			rtClient:    uc.Management.Wrangler.Mgmt.RoleTemplate(),
52			s:           status.NewStatus(),
53			clusterName: uc.ClusterName,
54		}, nil
55	}
