181			return err
182		}
183	
184		crbs = append(crbs, namespaceCRBs...)
185	
186		return p.ensureOnlyDesiredClusterRoleBindingsExists(crbs, rbac.GetPRTBOwnerLabel(prtb.Name), rbac.GetRTBLabel(prtb.ObjectMeta))
187	}
