48	func newRoleTemplateHandler(w *wrangler.Context, clusterManager *clustermanager.Manager) *roleTemplateHandler {
49		return &roleTemplateHandler{
50			crController:      w.RBAC.ClusterRole(),
51			rController:       w.RBAC.Role(),
52			rtController:      w.Mgmt.RoleTemplate(),
53			projectCache:      w.Mgmt.Project().Cache(),
54			clusterController: w.Mgmt.Cluster(),
55			clusterManager:    clusterManager,
56		}
57	}
58	
59	// OnChange creates all management plane cluster roles that will be needed. If there are no management plane rules in the role template, no cluster roles will be created.
60	func (r *roleTemplateHandler) OnChange(_ string, rt *v3.RoleTemplate) (*v3.RoleTemplate, error) {
61		if rt == nil || rt.DeletionTimestamp != nil {
62			return nil, nil
63		}
64	
65		var err error
66		rt, err = r.handleMigration(rt)
67		if err != nil {
68			return rt, err
69		}
70	
71		if !features.AggregatedRoleTemplates.Enabled() {
72			return rt, nil
73		}
74	
75		return rt, r.reconcileClusterRoles(rt)
76	}
77	
78	// handleMigration handles the migration of Role Templates when toggling the AggregatedRoleTemplates feature flag.
79	// If the feature flag is disabled, it removes the aggregation label and deletes any cluster roles that were created for aggregation.
80	// If the feature flag is enabled, it adds the aggregation label and deletes any legacy roles that were created before aggregation.
81	// TODO: To be removed once roletemplate aggregation is the only enabled RBAC model. https://github.com/rancher/rancher/issues/53743
82	func (r *roleTemplateHandler) handleMigration(rt *v3.RoleTemplate) (*v3.RoleTemplate, error) {
83		return handleAggregationMigration(
84			rt,
85			rt.Labels,
86			func(resource *v3.RoleTemplate, labels map[string]string) (*v3.RoleTemplate, error) {
87				rtCopy := resource.DeepCopy()
88				rtCopy.Labels = labels
89				return r.rtController.Update(rtCopy)
90			},
91			r.deleteClusterRoles,
92			r.deleteLegacyRoles,
93		)
94	}
95	
96	// reconcileClusterRoles is responsible for ensuring the right set of Cluster Roles exist. It deletes any owned by the Role Template that shouldn't exist.
97	func (r *roleTemplateHandler) reconcileClusterRoles(rt *v3.RoleTemplate) error {
98		rules, err := r.gatherRules(rt)
99		if err != nil {
100			return err
101		}
102	
103		desiredCRs, err := r.buildClusterRoles(rt, rules)
104		if err != nil {
105			return err
106		}
107		addOwnerReferenceToClusterRole(desiredCRs, rt)
108	
109		currentCRs, err := r.crController.List(metav1.ListOptions{LabelSelector: rbac.GetClusterRoleOwnerLabel(rt.Name)})
110		if err != nil {
111			return err
112		}
113	
114		// We want to keep desired Cluster Roles from this handler and the Cluster Roles created by the handler in
115		// pkg/controllers/managementuser/rbac/roletemplates/roletemplate_handler.go
116		// These are:
117		//	- Base Cluster Role
118		//  - Aggregating Cluster Role
119		//  - Promoted Cluster Role
120		//  - Aggregating Promoted Cluster Role
121		desiredCRNames := []string{
122			rt.Name,
123			rbac.AggregatedClusterRoleNameFor(rt.Name),
124			rbac.PromotedClusterRoleNameFor(rt.Name),
125			rbac.AggregatedClusterRoleNameFor(rbac.PromotedClusterRoleNameFor(rt.Name)),
126		}
127		for _, desiredCR := range desiredCRs {
128			desiredCRNames = append(desiredCRNames, desiredCR.Name)
129		}
130	
131		var returnedError error
