91	// clusterRolesForRoleTemplate builds and returns all needed Cluster Roles for the RoleTemplate using the given rules.
92	func (rth *roleTemplateHandler) clusterRolesForRoleTemplate(rt *v3.RoleTemplate) ([]*rbacv1.ClusterRole, error) {
93		res := []*rbacv1.ClusterRole{}
94		// We extract the promoted rules from the RoleTemplate, so we don't want to modify the original object
95		rtCopy := rt.DeepCopy()
96	
97		if rtCopy.Context == projectContext {
98			// ClusterRoles for promoted rules
99			var promotedClusterRoles []*rbacv1.ClusterRole
100			var err error
101			promotedClusterRoles, err = rth.buildPromotedClusterRoles(rt)
102			if err != nil {
103				return nil, err
104			}
105	
106			res = append(res, promotedClusterRoles...)
107		}
108	
109		// If the RoleTemplate refers to an external cluster role, don't modify/create it. Instead we will aggregate it.
110		if !rtCopy.External {
111			res = append(res, rbac.BuildClusterRole(rbac.ClusterRoleNameFor(rtCopy.Name), rtCopy.Name, rtCopy.Rules))
112		}
113		res = append(res, rbac.BuildAggregatingClusterRole(rtCopy, rbac.ClusterRoleNameFor))
114	
115		return res, nil
116	}
